#include <iostream>

// Pre: ultimo esta entre 0 y 10.
constexpr int suma_hasta(int ultimo) {
    int total{0};
    for (int numero = 1; numero <= ultimo; ++numero) {
        total += numero;
    }
    return total;
}

static_assert(suma_hasta(0) == 0);
static_assert(suma_hasta(4) == 10);

int main() {
    constexpr int modelo = suma_hasta(5);
    int caso{3};
    int calculado = suma_hasta(caso);
    std::cout << modelo << ':' << calculado;
    return 0;
}

